  async function github(method,p,body){const r=await fetch(urlFor(p),{method,headers:{...headers(),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await r.json().catch(()=>({}));if(!r.ok)throw Error(r.status===409?'GitHub 版本已變更。請重新讀取後再編輯。':`GitHub ${r.status}: ${result.message||'請確認 Token 權限'}`);return result}
