  function setupSections(){const scope=selectedScope(),select=$('#section'),previous=select.value;select.replaceChildren();let keys=scope==='home'?homeSections:scope==='apps'?['apps']:scope==='portal'?['copy','groups']:scope==='cards'?['cards']:scope==='resources'?['resources']:Object.keys(model).filter(k=>k!=='schemaVersion'&&k!=='code');for(const key of keys){const o=document.createElement('option');o.value=key;o.textContent=pretty(key);select.append(o)}if(keys.includes(previous))select.value=previous;$('#book-wrap').hidden=scope==='home'||scope==='apps'||scope==='portal';$('#section-wrap').hidden=scope==='resources'||scope==='apps'||scope==='cards';$('#pdf-upload').hidden=scope!=='resources'&&(scope!=='study'||dataVar!=='STUDY_DATA');$('#scope-help').textContent=scope==='home'?ui('按「編輯區塊」修改個人簡介、經歷、教學、獲獎、研究計畫與論文。','Choose a section to edit profile, experience, teaching, honors, projects, and publications.'):scope==='apps'?ui('新增、複製、排序或刪除 App；每筆可編輯中英文簡介、網址、QR Code 與 Chrome 擴充功能連結。儲存後首頁與獨立 Apps 入口會同步更新。','Add, duplicate, reorder, or delete apps. Edit bilingual summaries, URLs, QR images, and Chrome links. The homepage and Apps portal update together.'):scope==='portal'?ui('編輯聖經研讀首頁的中英文文字，以及舊約、新約與延伸資源卡片。','Edit bilingual Bible landing copy and Old/New Testament or resource cards.'):scope==='cards'?ui('在本卷書新增、編輯、排序或刪除中英文研讀卡片；卡片會隨視窗寬度自動排版。','Add, edit, reorder, or delete bilingual study cards for this book. The grid adapts to screen width.'):scope==='resources'?ui('這裡管理頁面下方「新增研讀資源」：筆記、參考連結及 PDF。約伯記也適用。','This edits the “Additional study resources” section near the bottom: notes, links, and PDFs. It also works for Job.'):ui(selectedBook()==='job-study'?'約伯記的文學分段、逐章摘要、對話、主題、經文、八課教案及教師提醒都在「編輯區塊」中。選擇區塊後，展開每一筆即可修改中英文細節。':'這裡可編輯本卷書的總覽、文學地圖、逐章內容、主題、教案與討論題。選擇「編輯區塊」，再展開每一筆即可修改中英文細節。',selectedBook()==='job-study'?'Job’s movements, chapters, dialogue, themes, verses, lessons, and teacher notes are in “Section.” Choose a section and expand an item to edit its bilingual details.':'Edit this book’s overview, literary map, chapters, themes, lessons, and questions. Choose a section, then expand an item for its bilingual details.');$('#preview').href=previewFor();renderScopeMap();updatePdfPlacement()}
  function renderScopeMap(){const scope=selectedScope(),box=$('#scope-map');box.hidden=scope!=='study'&&scope!=='resources';if(box.hidden)return;box.innerHTML=`<div class="map-card ${scope==='study'?'active':''}"><strong>${ui('卷書主體與頁首 PDF','Book body and top PDFs')}</strong><p>${ui('對應公開頁面的分類、總覽、逐章內容，以及「一眼讀懂全書」上方的投影片橫幅。','Controls the category, overview, chapter content, and PDF banner above the book summary.')}</p></div><div class="map-card ${scope==='resources'?'active':''}"><strong>${ui('頁尾筆記與資源','Bottom notes and resources')}</strong><p>${ui('對應公開頁面下方的「新增研讀資源」；適合補充筆記、外部連結、其他 PDF。','Controls “Additional study resources” near the bottom; use it for notes, outside links, and other PDFs.')}</p></div>`}
  function sectionHelp(){const scope=selectedScope(),help=$('#section-help');help.hidden=scope!=='study'&&scope!=='resources';if(help.hidden)return;const section=$('#section').value;help.textContent=scope==='resources'?ui('本區的每筆標題、內容及網址會顯示在公開卷書頁面的「新增研讀資源」。在此可修改已上傳 PDF 的顯示標題。','Each title, note, and link appears under “Additional study resources” on the public book page. You can edit an uploaded PDF’s display title here.'):section==='pdfFiles'?ui('此區每筆 PDF 會顯示在頁首投影片橫幅。修改「標題」中的繁中／English 文字即可更改按鈕名稱；PDF 原始檔名仍保留，請勿任意修改。','Each PDF appears in the top banner. Edit the Chinese/English “title” text to rename its button. Keep the stored filename unchanged.'):section==='category'?ui('這是頁面標題旁的書卷分類標籤，例如「十二小先知」，不會改動 PDF 或逐章內容。','This is the category badge by the page title, such as “The Twelve Minor Prophets.” It does not change PDFs or chapter text.'):ui('此區修改公開卷書頁面的主體內容；若要修改頁首 PDF 按鈕，請選「頁首橫幅 PDF 連結」。','This section edits the book page body. To rename a top PDF button, choose “PDF links in top banner.”')}
  function updatePdfPlacement(){const select=$('#pdf-placement');if(!select)return;const book=books.find(x=>x.slug===selectedBook()),generic=!!book&&book.slug!=='job-study'&&!book.slug.endsWith('-testament-overview');select.querySelector('option[value="featured"]').disabled=!generic;if(!generic)select.value='extra';else if(select.dataset.book!==selectedBook())select.value=selectedScope()==='study'?'featured':'extra';select.dataset.book=selectedBook();$('#pdf-placement-help').textContent=select.value==='featured'?ui('會在頁首投影片橫幅建立按鈕。上傳後可在「卷書主體與頁首 PDF → 頁首橫幅 PDF 連結」修改標題。','Adds a button to the top PDF banner. Edit it later under “Book body and top PDFs → PDF links in top banner.”'):ui('會在頁面下方「新增研讀資源」建立一筆。上傳後可在「頁尾筆記與資源」修改標題。','Adds an item under “Additional study resources.” Edit it later under “Bottom notes and resources.”')}
  const draftKey=()=>`sywan-editor-draft:${path}`;
  function saveDraft(){if(!model||!dirty)return message(ui('目前沒有需要儲存的修改。','No changes to save.'));try{const savedAt=new Date().toISOString(),payload=JSON.stringify({sha,model,savedAt});localStorage.setItem(draftKey(),payload);if(localStorage.getItem(draftKey())!==payload)throw Error('Draft read-back failed');draftSavedAt=savedAt;draftModel=clone(model);updateEditState();message(ui('✓ 草稿已儲存於此瀏覽器，尚未發布至 GitHub。','✓ Draft saved in this browser, not published to GitHub.'))}catch(e){updateEditState();message(ui('草稿儲存失敗；請檢查瀏覽器儲存空間或隱私設定。','Draft save failed; check browser storage or privacy settings.'),true)}}
  async function load(){if(!token)return;const scope=selectedScope(),book=selectedBook();path=pathFor();message('正在讀取 GitHub 最新版本…');$('#save').disabled=true;try{const result=await github('GET',path);sha=result.sha;source=decode(result.content);if(scope==='study'&&book==='job-study'){dataVar='JOB_DATA';model=JSON.parse(source)}else if(scope==='study'){const m=source.match(/window\.(STUDY_DATA|OT_DATA|NT_DATA)=([\s\S]*?);<\/script>/);if(!m)throw Error('此卷書的主體資料目前無法定位；請改用新增卡片或頁尾資源。');dataVar=m[1];model=JSON.parse(m[2])}else model=JSON.parse(source);publishedModel=clone(model);draftModel=clone(model);dirty=false;draftSaved=false;draftSavedAt='';let restored=false;try{const draft=JSON.parse(localStorage.getItem(draftKey())||'null');if(draft?.sha===sha&&draft.model){model=draft.model;draftModel=clone(model);dirty=true;draftSaved=true;draftSavedAt=draft.savedAt||'';restored=true}else if(draft)message(ui('發現舊草稿，但 GitHub 版本已變更。為避免覆蓋新資料，未自動載入。','An older draft exists, but GitHub changed. It was not loaded to avoid overwriting new data.'),true)}catch(e){}updateEditState();activeScope=scope;activeBook=book;setupSections();render();updateEditState();if(restored)message(ui('已載入此瀏覽器儲存的草稿，尚未發布。','Saved browser draft restored; not yet published.'));else if(!$('#status').classList.contains('error'))message(ui('已讀取 GitHub 最新版本。','Latest GitHub version loaded.')); $('#save').disabled=false}catch(e){model=null;$('#fields').replaceChildren();$('#section').replaceChildren();$('#book-wrap').hidden=scope==='home'||scope==='apps'||scope==='portal';$('#section-wrap').hidden=true;$('#pdf-upload').hidden=true;$('#scope-map').hidden=true;$('#section-help').hidden=true;$('#preview').href=previewFor();message(e.message,true)}}
  function pretty(key){return editorLang==='en'?(enLabels[key]||labels[key]||String(key)):(labels[key]||String(key))}
  function preview(value,i){if(typeof value==='string')return value;if(Array.isArray(value)){const bits=value.map(part=>typeof part==='string'?part:(part?.zh||part?.titleZh||(Array.isArray(part?.title)?part.title[0]:''))).filter(Boolean);return bits.slice(0,2).join(' · ')||`第 ${i+1} 項`}if(value&&typeof value==='object'){const title=Array.isArray(value.title)?value.title[0]:value.title;const name=Array.isArray(value.name)?value.name[0]:value.name;const v=value.titleZh||title||value.textZh||value.text||name||value.file||value.zh||value.refs;return typeof v==='string'?v:''}return `第 ${i+1} 項`}
  function itemPreview(nodePath,item,i){if(dataVar==='JOB_DATA'&&selectedScope()==='study'&&nodePath[0]==='chapters'&&Array.isArray(item))return `${ui('第','Chapter ')}${i+1}${ui('章','')} · ${(editorLang==='zh'?item[2]:item[3])||item[2]||item[0]||''}`;return preview(item,i)}
  function blankLike(x){if(Array.isArray(x))return x.map(blankLike);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,k==='year'?new Date().getFullYear():blankLike(v)]));if(typeof x==='number')return 0;if(typeof x==='boolean')return false;return ''}
